const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1400, height: 900 }, deviceScaleFactor: 1 });
  const pageErrors = [];
  const consoleErrors = [];
  page.on('pageerror', (error) => pageErrors.push(error.message));
  page.on('console', (message) => {
    if (message.type() === 'error') consoleErrors.push(message.text());
  });

  await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'networkidle' });
  const initial = {
    title: await page.title(),
    heading: await page.locator('h1').textContent(),
    status: await page.locator('#statusText').textContent(),
    bricks: await page.locator('#brickMetric').textContent(),
    canvasWidth: await page.locator('#scene').evaluate((node) => node.width),
    canvasHeight: await page.locator('#scene').evaluate((node) => node.height),
  };
  await page.screenshot({ path: '/tmp/car-crash-initial.png', fullPage: true });

  await page.click('#testButton');
  await page.waitForTimeout(3000);
  const duringTest = {
    status: await page.locator('#statusText').textContent(),
    speed: await page.locator('#speedMetric').textContent(),
    elapsed: await page.locator('#timeMetric').textContent(),
    bricks: await page.locator('#brickMetric').textContent(),
  };
  await page.screenshot({ path: '/tmp/car-crash-test.png', fullPage: true });

  await page.click('#resetButton');
  await page.waitForTimeout(120);
  const afterReset = {
    status: await page.locator('#statusText').textContent(),
    speed: await page.locator('#speedMetric').textContent(),
    elapsed: await page.locator('#timeMetric').textContent(),
    bricks: await page.locator('#brickMetric').textContent(),
  };

  console.log(JSON.stringify({ initial, duringTest, afterReset, pageErrors, consoleErrors }, null, 2));
  await browser.close();
})();

