function clamp(value, min, max) { return Math.max(min, Math.min(max, value)); }
function lerp(a, b, t) { return a + (b - a) * t; }
function dot(ax, ay, bx, by) { return ax * bx + ay * by; }
function cross(ax, ay, bx, by) { return ax * by - ay * bx; }
function magnitude(x, y) { return Math.sqrt(x * x + y * y); }
function sign(value) { return value < 0 ? -1 : 1; }

function seededRandom() {
  visualSeed = (visualSeed * 1664525 + 1013904223) >>> 0;
  return visualSeed / 4294967296;
}

function setStatus(text, active) {
  statusText.textContent = text;
  const dot = document.querySelector(".status-chip i");
  dot.style.background = active ? "var(--amber)" : "var(--cyan)";
  dot.style.boxShadow = active ? "0 0 0 4px rgba(255,184,90,0.12), 0 0 14px var(--amber)" : "0 0 0 4px rgba(106,228,219,0.11), 0 0 14px var(--cyan)";
}

function updateControlLabels() {
  speedValue.textContent = `${settings.speed} m/s`;
  columnsValue.textContent = `${settings.columns} bricks`;
  rowsValue.textContent = `${settings.rows} rows`;
  layersValue.textContent = `${settings.layers} layers`;
  massValue.textContent = `${settings.brickMass.toFixed(1)} kg`;
  const inputs = [speedInput, columnsInput, rowsInput, layersInput, massInput];
  inputs.forEach((input) => {
    const min = Number(input.min);
    const max = Number(input.max);
    const value = Number(input.value);
    input.style.setProperty("--fill", `${((value - min) / (max - min)) * 100}%`);
  });
}

