  const totalInvMass = a.invMass + b.invMass;
  if (totalInvMass <= 0) return 0;
  const correction = Math.max(penetration - 0.001, 0) * 0.84 / totalInvMass;
  a.x -= nx * correction * a.invMass;
  a.y -= ny * correction * a.invMass;
  b.x += nx * correction * b.invMass;
  b.y += ny * correction * b.invMass;

  const contactX = (a.x + b.x) * 0.5;
  const contactY = (a.y + b.y) * 0.5;
  const avx = a.vx - a.angVel * (contactY - a.y);
  const avy = a.vy + a.angVel * (contactX - a.x);
  const bvx = b.vx - b.angVel * (contactY - b.y);
  const bvy = b.vy + b.angVel * (contactX - b.x);
  const rvx = bvx - avx;
  const rvy = bvy - avy;
  const normalVelocity = dot(rvx, rvy, nx, ny);
  let impulseMagnitude = 0;

  if (normalVelocity < 0) {
    impulseMagnitude = -(1 + restitution) * normalVelocity / totalInvMass;
    const ix = nx * impulseMagnitude;
    const iy = ny * impulseMagnitude;
    applyImpulse(a, -ix, -iy, contactX, contactY);
    applyImpulse(b, ix, iy, contactX, contactY);

    const tangentX = -ny;
    const tangentY = nx;
    const tangentVelocity = dot(rvx, rvy, tangentX, tangentY);
    let frictionImpulse = -tangentVelocity / totalInvMass;
    const maxFriction = Math.abs(impulseMagnitude) * friction;
    frictionImpulse = clamp(frictionImpulse, -maxFriction, maxFriction);
    const fix = tangentX * frictionImpulse;
    const fiy = tangentY * frictionImpulse;
    applyImpulse(a, -fix, -fiy, contactX, contactY);
    applyImpulse(b, fix, fiy, contactX, contactY);
  }

  if (impulseMagnitude > 0.12 || Math.abs(normalVelocity) > 0.3) {
    wake(a);
    wake(b);
  }
  return impulseMagnitude;
}

function resolveGround(body) {
  const ext = halfExtents(body);
  if (body.y - ext.y >= 0) return 0;
  const penetration = -body.y + ext.y;
  body.y += penetration * 0.9;
  if (body.vy < 0) {
    const impact = -body.vy;
    body.vy = impact * (body.type === "brick" ? PHYSICS.brickRestitution : 0.045);
    body.vx *= Math.max(0, 1 - PHYSICS.groundFriction * 0.11);
    body.angVel *= 0.78;
    if (body.type === "brick" && impact > 0.15) wake(body);
    return impact;
  }
  body.vy = Math.max(0, body.vy);
  body.vx *= Math.exp(-PHYSICS.groundFriction * 0.30 * PHYSICS.fixedDt);
  body.angVel *= Math.exp(-PHYSICS.groundFriction * 0.55 * PHYSICS.fixedDt);
  return 0;
}

function addImpactEffects(x, y, impulse) {
  impactCount += 1;
  cameraShake = Math.max(cameraShake, clamp(impulse / 80, 1, 9));
  lastImpactX = x;
  const count = Math.min(24, 8 + Math.floor(impulse / 28));
  for (let i = 0; i < count; i += 1) {
    const angle = Math.PI * (0.08 + seededRandom() * 0.78);
    const speed = 1.2 + seededRandom() * 4.4;
    particles.push({
