function addImpactEffects(x, y, impulse) {
  impactCount += 1;
  cameraShake = Math.max(cameraShake, clamp(impulse / 80, 1, 9));
  lastImpactX = x;
  const count = Math.min(24, 8 + Math.floor(impulse / 28));
  for (let i = 0; i < count; i += 1) {
    const angle = Math.PI * (0.08 + seededRandom() * 0.78);
    const speed = 1.2 + seededRandom() * 4.4;
    particles.push({
      x: x + (seededRandom() - 0.5) * 0.35,
      y: y + seededRandom() * 0.38,
      vx: Math.cos(angle) * speed * (0.7 + impulse / 300),
      vy: Math.sin(angle) * speed * (0.7 + impulse / 300),
      life: 0.28 + seededRandom() * 0.46,
      maxLife: 0.28 + seededRandom() * 0.46,
      size: 0.025 + seededRandom() * 0.055,
      dust: seededRandom() > 0.35,
    });
  }
}

function buildSpatialGrid() {
  const grid = new Map();
  const cellSize = 0.72;
  for (const brick of scene.bricks) {
    const ext = halfExtents(brick);
    const minX = Math.floor((brick.x - ext.x) / cellSize);
    const maxX = Math.floor((brick.x + ext.x) / cellSize);
    const minY = Math.floor((brick.y - ext.y) / cellSize);
    const maxY = Math.floor((brick.y + ext.y) / cellSize);
    for (let gx = minX; gx <= maxX; gx += 1) {
      for (let gy = minY; gy <= maxY; gy += 1) {
        const key = `${gx}:${gy}`;
        const bucket = grid.get(key);
        if (bucket) bucket.push(brick); else grid.set(key, [brick]);
      }
    }

