function resolveContact(a, b, friction, restitution) {
  const overlap = aabbOverlap(a, b);
  if (overlap.x <= 0 || overlap.y <= 0) return 0;
  let nx = 0;
  let ny = 0;
  let penetration;
  if (overlap.x < overlap.y) {
    nx = overlap.dx >= 0 ? 1 : -1;
    penetration = overlap.x;
  } else {
    ny = overlap.dy >= 0 ? 1 : -1;
    penetration = overlap.y;
  }

  const totalInvMass = a.invMass + b.invMass;
  if (totalInvMass <= 0) return 0;
  const correction = Math.max(penetration - 0.001, 0) * 0.84 / totalInvMass;
  a.x -= nx * correction * a.invMass;
  a.y -= ny * correction * a.invMass;
  b.x += nx * correction * b.invMass;
  b.y += ny * correction * b.invMass;

  const contactX = (a.x + b.x) * 0.5;
  const contactY = (a.y + b.y) * 0.5;
  const avx = a.vx - a.angVel * (contactY - a.y);
  const avy = a.vy + a.angVel * (contactX - a.x);
  const bvx = b.vx - b.angVel * (contactY - b.y);
  const bvy = b.vy + b.angVel * (contactX - b.x);
  const rvx = bvx - avx;
  const rvy = bvy - avy;
  const normalVelocity = dot(rvx, rvy, nx, ny);
  let impulseMagnitude = 0;

  if (normalVelocity < 0) {
    impulseMagnitude = -(1 + restitution) * normalVelocity / totalInvMass;

