function solveCarContacts() {
  let totalImpulse = 0;
  const car = scene.car;
  for (const brick of scene.bricks) {
    const overlap = aabbOverlap(car, brick);
    if (overlap.x <= 0 || overlap.y <= 0) continue;
    wakeNeighborhood(brick);
    const impulse = resolveContact(car, brick, 0.48, 0.07, true);
    totalImpulse += impulse;
    if (impulse > 0.3) {
      car.hitFlash = Math.min(1, car.hitFlash + impulse / 34);
      addImpactEffects(brick.x, Math.max(0.06, brick.y), impulse);
    }
  }
  if (totalImpulse > 0) {
    car.vx *= 0.999;
    car.vy *= 0.995;
    car.angle = clamp(car.angle, -0.17, 0.17);
    car.angVel = clamp(car.angVel, -1.1, 1.1);
  }
  return totalImpulse;
}

