const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({headless:true});
  const page = await browser.newPage({viewport:{width:1200,height:800}});
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto('http://127.0.0.1:4173/index.html', {waitUntil:'networkidle'});
  await page.locator('#columnsInput').fill('16');
  await page.locator('#rowsInput').fill('10');
  await page.locator('#layersInput').fill('3');
  await page.locator('#massInput').fill('5');
  const changed = {
    columns: await page.locator('#columnsValue').textContent(),
    rows: await page.locator('#rowsValue').textContent(),
    layers: await page.locator('#layersValue').textContent(),
    mass: await page.locator('#massValue').textContent(),
    bricks: await page.locator('#brickMetric').textContent(),
  };
  await page.click('#testButton');
  await page.waitForTimeout(650);
  const impact = {
    status: await page.locator('#statusText').textContent(),
    moving: await page.locator('#brickMetric').textContent(),
  };
  await page.click('#resetButton');
  const reset = {
    status: await page.locator('#statusText').textContent(),
    bricks: await page.locator('#brickMetric').textContent(),
  };
  console.log(JSON.stringify({changed, impact, reset, errors}, null, 2));
  await browser.close();
})();

